package com.joysistvi.CyberAccess.controller;
import com.joysistvi.CyberAccess.model.Order; import com.joysistvi.CyberAccess.service.OrderServiceImpl; import java.sql.SQLException; import java.util.List;
public class OrderController {private final OrderServiceImpl service;public OrderController(){this(new OrderServiceImpl());}public OrderController(OrderServiceImpl s){service=s;}public List<Order> getAll()throws SQLException{return service.getAll();}public List<Order> getByUser(int id)throws SQLException{return service.getByUser(id);}public Order getById(int id)throws SQLException{return service.getById(id);}public void create(Order x)throws SQLException{service.create(x);}public boolean update(Order x)throws SQLException{return service.update(x);}public boolean setStatus(int id,String status)throws SQLException{return service.setStatus(id,status);}public boolean delete(int id)throws SQLException{return service.delete(id);}}
